// Learn more: https://docs.expo.dev/guides/customizing-metro
const fs = require('fs');
const path = require('path');
const { getDefaultConfig } = require('expo/metro-config');

const config = getDefaultConfig(__dirname);

// The QVAC worker bundle is generated by the @qvac/sdk Expo plugin during `expo prebuild`
// (EAS builds always run it). In Expo Go / plain `expo start` it doesn't exist yet, and the
// app runs the labelled demo engine instead, so resolve it to an empty module there.
const WORKER = '@qvac/sdk/worker.mobile.bundle';
const workerFile = path.join(__dirname, 'node_modules', '@qvac', 'sdk', 'dist', 'worker.mobile.bundle.js');

const upstream = config.resolver.resolveRequest;
config.resolver.resolveRequest = (context, moduleName, platform) => {
  if (moduleName === WORKER && !fs.existsSync(workerFile)) {
    return { type: 'empty' };
  }
  return upstream ? upstream(context, moduleName, platform) : context.resolveRequest(context, moduleName, platform);
};

module.exports = config;
